@namespace sv_cd836899640945a9a3cb7f8ed9778cdb.Components.Pages.Settings
@using sv_cd836899640945a9a3cb7f8ed9778cdb.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Appearance</h2>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="form-group">
            <h3>Theme</h3>
            <div class="radio-group">
                <label>
                    <input type="radio" name="theme" value="Light"
                           checked="@(_theme == "Light")"
                           @onchange="() => _theme = &quot;Light&quot;" />
                    Light
                </label>
                <label>
                    <input type="radio" name="theme" value="Dark"
                           checked="@(_theme == "Dark")"
                           @onchange="() => _theme = &quot;Dark&quot;" />
                    Dark
                </label>
                <label>
                    <input type="radio" name="theme" value="System"
                           checked="@(_theme == "System")"
                           @onchange="() => _theme = &quot;System&quot;" />
                    System
                </label>
            </div>
        </div>

        <div class="form-group">
            <h3>Font Size</h3>
            <div class="radio-group">
                <label>
                    <input type="radio" name="fontSize" value="Small"
                           checked="@(_fontSize == "Small")"
                           @onchange="() => _fontSize = &quot;Small&quot;" />
                    Small
                </label>
                <label>
                    <input type="radio" name="fontSize" value="Medium"
                           checked="@(_fontSize == "Medium")"
                           @onchange="() => _fontSize = &quot;Medium&quot;" />
                    Medium
                </label>
                <label>
                    <input type="radio" name="fontSize" value="Large"
                           checked="@(_fontSize == "Large")"
                           @onchange="() => _fontSize = &quot;Large&quot;" />
                    Large
                </label>
            </div>
        </div>

        <div class="form-group">
            <label for="language">Language</label>
            <select id="language" @bind="_language">
                <option value="en">English</option>
                <option value="es">Spanish</option>
                <option value="fr">French</option>
                <option value="de">German</option>
                <option value="ja">Japanese</option>
            </select>
        </div>

        <div class="form-group">
            <label class="toggle">
                <input type="checkbox" @bind="_compactMode" />
                <span>Compact Mode</span>
            </label>
        </div>

        <div class="live-preview" style="@PreviewStyle">
            <h4>Live Preview</h4>
            <p>This is how your content will look with the selected settings.</p>
            <p>The quick brown fox jumps over the lazy dog.</p>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync">Save</button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">Appearance saved!</div>
        }
    }
</div>

@code {
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _loading = true;
    private bool _showSuccess;

    private string PreviewStyle
    {
        get
        {
            var bg = _theme switch
            {
                "Dark" => "background-color: #1e1e1e; color: #ffffff;",
                "Light" => "background-color: #ffffff; color: #000000;",
                _ => "background-color: #f5f5f5; color: #333333;"
            };

            var font = _fontSize switch
            {
                "Small" => "font-size: 12px;",
                "Large" => "font-size: 18px;",
                _ => "font-size: 14px;"
            };

            var padding = _compactMode ? "padding: 8px;" : "padding: 16px;";

            return $"{bg} {font} {padding} border: 1px solid #ccc; border-radius: 4px; margin-top: 12px;";
        }
    }

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

@page "/settings"
@namespace sv_cd836899640945a9a3cb7f8ed9778cdb.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection"
                    OnSectionSelected="section => _activeSection = section" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

