::deep .sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
}

::deep .current-badge {
    font-size: 0.8rem;
    background: #e3f2fd;
    color: #1976d2;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
}

::deep .error-message {
    color: #d32f2f;
    margin-bottom: 0.5rem;
    font-size: 0.9rem;
}

::deep .radio-group {
    display: flex;
    gap: 1.5rem;
    margin-bottom: 0.5rem;
}

::deep .radio-group label {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    cursor: pointer;
    font-weight: normal;
}

::deep .live-preview {
    margin-top: 1.5rem;
    transition: all 0.3s ease;
}

::deep .modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

::deep .modal {
    background: white;
    padding: 1.5rem;
    border-radius: 8px;
    max-width: 400px;
    width: 90%;
}

::deep .modal h3 {
    margin-top: 0;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-8px); }
    to { opacity: 1; transform: translateY(0); }
}

